import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "../ui/dialog";
import { Button } from "../ui/button";
import { CheckCircle2, XCircle, Loader2, AlertTriangle } from "lucide-react";
import StatusBadge from "../ui/StatusBadge";
import { cn } from "../../lib/utils";
import { formatCurrency, currencyForMarket } from "../../lib/format";
import { getExitCondition } from "../../lib/exitCondition";

export default function MonitorModal({ 
  open, 
  onClose, 
  positions, 
  isLoading,
  onConfirmExits,
  restoreSelection = null
}) {
  const [selectedExits, setSelectedExits] = useState([]);

  // When an exit queue is cancelled the Monitor reopens with the positions
  // not yet exited still selected (positions.md §Daily Position Monitor Exit Queue).
  useEffect(() => {
    if (open && restoreSelection) setSelectedExits(restoreSelection);
  }, [open, restoreSelection]);

  // ST-11 (BLG-FE-231, v9.14): suggestions follow the shared §8 predicate, so
  // risk-off (the position's risk_off_exit flag) takes precedence and a stop is
  // suggested only after grace (positions.md §Monitor Suggestions).
  const getPositionStatus = (position) => {
    const { riskOff, stopBreach } = getExitCondition(position);
    if (riskOff) return { status: "exit", reason: "Market risk off" };
    if (stopBreach) return { status: "exit", reason: "Stop price hit" };
    const stop = Number(position.current_trailing_stop);
    const price = Number(position.current_price);
    if (position.grace_period === true && stop > 0 && price > 0 && price <= stop) {
      return { status: "hold", reason: "In grace: stop not enforced" };
    }
    return { status: "hold", reason: "Position OK" };
  };

  const toggleExit = (positionId) => {
    setSelectedExits(prev => 
      prev.includes(positionId)
        ? prev.filter(id => id !== positionId)
        : [...prev, positionId]
    );
  };

  // "Exit Selected" submits nothing itself: it hands the selected positions,
  // in display order and with their suggestion, to the Dashboard's exit queue.
  const handleConfirm = () => {
    const exits = positions
      .filter(p => selectedExits.includes(p.id))
      .map(p => ({ position: p, reason: getPositionStatus(p).reason }));
    setSelectedExits([]);
    onConfirmExits(exits);
  };

  const exitSuggestions = positions?.filter(p => getPositionStatus(p).status === "exit") || [];
  // A restored selection can name a position whose exit was recorded after
  // Cancel; count only positions still listed.
  const selectedCount = selectedExits.filter(id => positions?.some(p => p.id === id)).length;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="bg-slate-900 border-slate-700 text-white !max-w-2xl max-h-[80vh] overflow-hidden !flex !flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <div className="p-2 rounded-lg bg-amber-500/20">
              <AlertTriangle className="w-5 h-5 text-amber-400" />
            </div>
            Daily Position Monitor
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto py-4">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-slate-500" />
            </div>
          ) : positions?.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-slate-600 dark:text-slate-400">No open positions to monitor</p>
            </div>
          ) : (
            <div className="space-y-3">
              {positions?.map((position) => {
                const { status, reason } = getPositionStatus(position);
                const isExitSuggested = status === "exit";
                const isSelected = selectedExits.includes(position.id);
                const positionCurrency = currencyForMarket(position.market);

                return (
                  <div
                    key={position.id}
                    data-testid="monitor-row"
                    data-ticker={position.ticker}
                    data-suggestion={status}
                    onClick={() => isExitSuggested && toggleExit(position.id)}
                    className={cn(
                      "p-4 rounded-xl border transition-all",
                      isExitSuggested && "cursor-pointer",
                      isSelected 
                        ? "bg-rose-500/10 border-rose-500/30" 
                        : isExitSuggested
                          ? "bg-amber-500/5 border-amber-500/20 hover:border-amber-500/40"
                          : "bg-slate-800/30 border-slate-700/50"
                    )}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        {isExitSuggested ? (
                          isSelected ? (
                            <div className="p-2 rounded-lg bg-rose-500/20">
                              <XCircle className="w-5 h-5 text-rose-400" />
                            </div>
                          ) : (
                            <div className="p-2 rounded-lg bg-amber-500/20">
                              <AlertTriangle className="w-5 h-5 text-amber-400" />
                            </div>
                          )
                        ) : (
                          <div className="p-2 rounded-lg bg-emerald-500/20">
                            <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                          </div>
                        )}
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="font-semibold text-white">{position.ticker}</span>
                            <span className="text-xs px-2 py-0.5 rounded-full bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-700">
                              {position.market}
                            </span>
                          </div>
                          <p className="text-xs text-slate-600 dark:text-slate-400 mt-0.5">{reason}</p>
                        </div>
                      </div>
                      <StatusBadge status={status} />
                    </div>
                    
                    {isExitSuggested && (
                      <div className="mt-3 pt-3 border-t border-slate-700/50 grid grid-cols-3 gap-4 text-sm">
                        <div>
                          <p className="text-xs text-slate-600 dark:text-slate-400">Current</p>
                          <p className="text-white font-medium">
                            {position.current_price != null ? formatCurrency(position.current_price, { currency: positionCurrency }) : "—"}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-slate-600 dark:text-slate-400">Stop</p>
                          <p className="text-rose-400 font-medium">
                            {position.stop_price != null ? formatCurrency(position.stop_price, { currency: positionCurrency }) : "—"}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-slate-600 dark:text-slate-400">Entry</p>
                          <p className="text-slate-300">
                            {formatCurrency(position.entry_price, { currency: positionCurrency })}
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <DialogFooter className="border-t border-slate-700 pt-4">
          <div className="flex items-center justify-between w-full">
            <p className="text-sm text-slate-600 dark:text-slate-400">
              {selectedCount > 0 
                ? `${selectedCount} position${selectedCount > 1 ? "s" : ""} selected for exit`
                : exitSuggestions.length > 0 
                  ? `${exitSuggestions.length} exit suggestion${exitSuggestions.length > 1 ? "s" : ""}`
                  : "All positions healthy"
              }
            </p>
            <div className="flex gap-2">
              <Button 
                variant="ghost" 
                onClick={onClose} 
                className="text-slate-600 dark:text-slate-400 hover:text-white hover:bg-slate-800"
              >
                Close
              </Button>
              {selectedCount > 0 && (
                <Button 
                  onClick={handleConfirm}
                  className="bg-rose-600 hover:bg-rose-700 text-white"
                >
                  Exit Selected
                </Button>
              )}
            </div>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
